diff --git a/src/Handler/CurlFactory.php b/src/Handler/CurlFactory.php
index a6fcae555..ced94afca 100644
--- a/src/Handler/CurlFactory.php
+++ b/src/Handler/CurlFactory.php
@@ -393,29 +393,33 @@ private function applyHandlerOptions(EasyHandle $easy, array &$conf): void
             }
         }

-        if (isset($options['sink'])) {
-            $sink = $options['sink'];
-            if (!\is_string($sink)) {
-                $sink = \GuzzleHttp\Psr7\stream_for($sink);
-            } elseif (!\is_dir(\dirname($sink))) {
-                // Ensure that the directory exists before failing in curl.
-                throw new \RuntimeException(\sprintf(
-                    'Directory %s does not exist for sink value of %s',
-                    \dirname($sink),
-                    $sink
-                ));
+        // Do not connect a sink for HEAD requests.
+        if ($easy->request->getMethod() !== 'HEAD') {
+            if (isset($options['sink'])) {
+                $sink = $options['sink'];
+                if (!\is_string($sink)) {
+                    $sink = \GuzzleHttp\Psr7\stream_for($sink);
+                } elseif (!\is_dir(\dirname($sink))) {
+                    // Ensure that the directory exists before failing in curl.
+                    throw new \RuntimeException(\sprintf(
+                        'Directory %s does not exist for sink value of %s',
+                        \dirname($sink),
+                        $sink
+                    ));
+                } else {
+                    $sink = new LazyOpenStream($sink, 'w+');
+                }
+                $easy->sink = $sink;
+                $conf[\CURLOPT_WRITEFUNCTION] = static function ($ch, $write) use ($sink): int {
+                    return $sink->write($write);
+                };
             } else {
-                $sink = new LazyOpenStream($sink, 'w+');
+                // Use a default temp stream if no sink was set.
+                $conf[\CURLOPT_FILE] = \fopen('php://temp', 'w+');
+                $easy->sink = Psr7\stream_for($conf[\CURLOPT_FILE]);
             }
-            $easy->sink = $sink;
-            $conf[\CURLOPT_WRITEFUNCTION] = static function ($ch, $write) use ($sink): int {
-                return $sink->write($write);
-            };
-        } else {
-            // Use a default temp stream if no sink was set.
-            $conf[\CURLOPT_FILE] = \fopen('php://temp', 'w+');
-            $easy->sink = Psr7\stream_for($conf[\CURLOPT_FILE]);
         }
+
         $timeoutRequiresNoSignal = false;
         if (isset($options['timeout'])) {
             $timeoutRequiresNoSignal |= $options['timeout'] < 1;
diff --git a/tests/Handler/CurlFactoryTest.php b/tests/Handler/CurlFactoryTest.php
